package com.dealhunter.app;
import java.util.*;import java.net.*;import org.json.*;
final class GameDeals {
 static boolean isGame(String title){return title.toLowerCase(Locale.US).matches(".*\\b(video games?|steam|playstation|ps4|ps5|xbox|nintendo switch|pc game|gog|epic games)\\b.*")&&!title.toLowerCase(Locale.US).matches(".*\\b(controller|headset|console bundle|gift card|subscription|expired|sold out)\\b.*");}
 static int scan(ArrayList<JSONObject> deals,HashSet<String> seen,android.content.SharedPreferences p){try{URLConnection c=new URL("https://www.cheapshark.com/api/1.0/deals?onSale=1&pageSize=60&sortBy=Savings").openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","DealHunter/1.0");String body;try(java.io.InputStream in=c.getInputStream();java.util.Scanner s=new java.util.Scanner(in,"UTF-8")){body=s.useDelimiter("\\A").hasNext()?s.next():"[]";}JSONArray a=new JSONArray(body);for(int i=0;i<a.length();i++){JSONObject g=a.getJSONObject(i);double price=g.getDouble("salePrice"),normal=g.getDouble("normalPrice");if(normal<=0||price<0)continue;int discount=(int)Math.floor(100*(normal-price)/normal+0.000001);if(discount<50)continue;String url="https://www.cheapshark.com/redirect?dealID="+java.net.URLEncoder.encode(g.getString("dealID"),"UTF-8");if(!seen.add(url))continue;JSONObject d=new JSONObject().put("title",g.getString("title")+String.format(Locale.US," — $%.2f",price)).put("url",url).put("source","CheapShark · PC").put("discount",discount).put("category","Games").put("direct",url);PriceHistory.record(p,d);deals.add(d);}return 1;}catch(Exception e){return 0;}}
}
